#if APP_TESTS
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Threading;
namespace FileCompass {
 internal static class UndoHistoryTests {
  internal static int Run(string root){Directory.CreateDirectory(root);var checks=new List<string>();MainWindow main=null;Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception(label);checks.Add(label);};
   try{SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(Dispatcher.CurrentDispatcher));string folder=Directory.CreateDirectory(Path.Combine(root,"files")).FullName;
    check(HelpContent.ContextTopic(typeof(UndoTransactionsWindow))=="copy","Transaction history F1 opens the operations help topic");
    string a=Path.Combine(folder,"a.txt"),b=Path.Combine(folder,"b.txt"),c=Path.Combine(folder,"c.txt");File.WriteAllText(a,"same file");var first=UndoReceipt.Capture(a,a,true);File.Move(a,b);first=UndoReceipt.Committed(first,b);var g1=SafeUndo.Record("Rename A to B",new[]{first});check(UndoEligibility.Inspect(g1,true,CancellationToken.None).Available.Count==1,"A completed rename is initially reversible");
    var second=UndoReceipt.Capture(b,b,true);File.Move(b,c);second=UndoReceipt.Committed(second,c);var g2=SafeUndo.Record("Rename B to C",new[]{second});check(UndoEligibility.Inspect(g1,true,CancellationToken.None).Available.Count==0,"A subsequent rename disables the earlier rename");check(UndoEligibility.Inspect(g2,true,CancellationToken.None).Available.Count==1,"The later rename remains reversible");UndoEligibility.ApplyAvailable(g2,new[]{second},CancellationToken.None);check(UndoEligibility.Inspect(g1,true,CancellationToken.None).Available.Count==1,"Undoing the later rename re-enables its predecessor");UndoEligibility.ApplyAvailable(g1,new[]{first},CancellationToken.None);check(File.Exists(a)&&g1.Items.Count==0&&SafeUndo.Groups().Contains(g1),"Completed undo remains visible in history");
    string removed=Path.Combine(folder,"removed.txt");var missingProof=UndoReceipt.Capture(a,a,true);File.Move(a,removed);missingProof=UndoReceipt.Committed(missingProof,removed);var missing=SafeUndo.Record("Rename then delete",new[]{missingProof});File.Delete(removed);var inspection=UndoEligibility.Inspect(missing,true,CancellationToken.None);check(inspection.Available.Count==0&&inspection.Problems.Any(x=>x.Contains(L.Text("undoHistory.missing"))),"Deleting a renamed file disables its rename with an explicit reason");File.WriteAllText(removed,"replacement");check(UndoEligibility.Inspect(missing,true,CancellationToken.None).Available.Count==0,"A replacement file with the same name cannot inherit an Undo receipt");
    string older=Directory.CreateDirectory(Path.Combine(folder,"older-folder")).FullName;var earlier=SafeUndo.Record("Older independent folder",new[]{UndoReceipt.Capture(older,null,false)});string newer=Directory.CreateDirectory(Path.Combine(folder,"newer-folder")).FullName;var latest=SafeUndo.Record("Newer independent folder",new[]{UndoReceipt.Capture(newer,null,false)});UndoEligibility.ApplyAvailable(earlier,earlier.Items.ToArray(),CancellationToken.None);check(!Directory.Exists(older)&&Directory.Exists(newer)&&latest.Items.Count==1,"An older independent transaction can be undone without undoing the latest one");
    string source=Directory.CreateDirectory(Path.Combine(folder,"source")).FullName,target=Directory.CreateDirectory(Path.Combine(folder,"target")).FullName;string tree=Directory.CreateDirectory(Path.Combine(source,"tree")).FullName;Directory.CreateDirectory(Path.Combine(tree,"child"));File.WriteAllText(Path.Combine(tree,"child","copy.txt"),"copy payload");CopyResult copied;using(var control=new CopyControl())copied=new CopyEngine(new CopyOptions{Target=target},control,x=>new CopyDecision(CopyChoice.Skip),x=>{}).Run(new[]{tree});var batch=SafeUndo.Record("Copy directory",copied.Undo);inspection=UndoEligibility.Inspect(batch,true,CancellationToken.None);check(inspection.Available.Count==3,"Copied directory trees are eligible bottom-up including owned children");string extra=Path.Combine(target,"tree","child","user.txt");File.WriteAllText(extra,"user data");inspection=UndoEligibility.Inspect(batch,true,CancellationToken.None);check(inspection.Available.Count==1&&inspection.Total==3,"New files make the copied folder batch partially reversible");UndoEligibility.ApplyAvailable(batch,inspection.Available.ToArray(),CancellationToken.None);check(File.ReadAllText(extra)=="user data"&&batch.Items.Count==2&&!File.Exists(Path.Combine(target,"tree","child","copy.txt")),"Partial Undo preserves user-added files and keeps unavailable steps in history");
    File.WriteAllText(Path.Combine(source,"changed.txt"),"original");using(var control=new CopyControl())copied=new CopyEngine(new CopyOptions{Target=target},control,x=>new CopyDecision(CopyChoice.Skip),x=>{}).Run(new[]{Path.Combine(source,"changed.txt")});var changed=SafeUndo.Record("Changed copy",copied.Undo);string changedFile=Path.Combine(target,"changed.txt");var modified=File.GetLastWriteTimeUtc(changedFile);File.WriteAllText(changedFile,"modified");File.SetLastWriteTimeUtc(changedFile,modified);check(UndoEligibility.Inspect(changed,true,CancellationToken.None).Available.Count==0,"Final verification detects changed content even with identical size and restored timestamp");
    main=new MainWindow(folder){Left=-18000,Top=-18000,WindowStartupLocation=WindowStartupLocation.Manual};main.Show();NavigationTests.WaitPanels(main);main.VerifyUndoHistory(missing,latest,checks,check);main.Close();main=null;File.WriteAllLines(Path.Combine(root,"result.txt"),checks.Concat(new[]{"PASS: "+checks.Count+" checks"}));return 0;
   }catch(Exception ex){File.WriteAllText(Path.Combine(root,"result.txt"),"FAIL after "+checks.Count+" checks\n"+String.Join("\n",checks)+"\n"+ex);return 1;}finally{if(main!=null)main.Close();}
  }
 }
 public partial class MainWindow {
  internal void VerifyUndoHistory(UndoGroup missing,UndoGroup latest,List<string> checks,Action<bool,string> check){
   var undo=FluentUiTests.Children<Button>(this).First(x=>FluentUiTests.Children<Image>(x).Any(i=>Convert.ToString(i.Tag)=="undo"));var toolbar=undo.Parent as WrapPanel;int index=toolbar.Children.IndexOf(undo);check(index>0&&toolbar.Children[index-1] is StackPanel&&FluentUiTests.Children<Image>(toolbar.Children[index-1]).Any(x=>Convert.ToString(x.Tag)=="back"),"Undo toolbar button follows the left/right arrows");
   operationJournal.Records.Insert(0,new OperationRecord{Title="Deletion",Ended=DateTime.Now,State=L.Code("state.completed"),Items=new List<OperationItem>{new OperationItem{Source="deleted.txt",State=L.Code("state.completed")}}});
   OpenUndoTransactions();NavigationTests.Wait(undoTransactionsWindow.RefreshTask);var rows=undoTransactionsWindow.Transactions.Items.Cast<UndoHistoryEntry>().ToArray();var disabled=rows.Single(x=>Object.ReferenceEquals(x.Group,missing));var enabled=rows.Single(x=>Object.ReferenceEquals(x.Group,latest));check(disabled.Inspection.Available.Count==0&&enabled.Inspection.Available.Count==1&&disabled.Tint.ToString()!=enabled.Tint.ToString(),"Native history highlights available and unavailable transactions differently");check(rows.Any(x=>x.Title=="Deletion"&&x.Group==null&&!String.IsNullOrEmpty(x.Reason)),"Irreversible journal transactions are visible with a reason");undoTransactionsWindow.Transactions.SelectedItem=disabled;check(!undoTransactionsWindow.UndoButton.IsEnabled,"Unavailable transactions cannot be triggered by the Undo button");undoTransactionsWindow.Transactions.SelectedItem=enabled;check(undoTransactionsWindow.UndoButton.IsEnabled,"Selecting an available transaction enables Undo");
   var mixed=new OperationRecord{Title="Mixed copy and overwrite",Undo=latest,Ended=DateTime.Now,State=L.Code("state.completed"),Items=new List<OperationItem>{new OperationItem{Source="original.txt",Target=Path.Combine(active.CurrentPath,"overwritten.txt"),State=L.Code("state.completed")}}};operationJournal.Records.Insert(0,mixed);FluentUiTests.Children<Button>(undoTransactionsWindow).Single(x=>Convert.ToString(x.Content)==L.Text("action.refresh")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));NavigationTests.Wait(undoTransactionsWindow.RefreshTask);var mixedRow=undoTransactionsWindow.Transactions.Items.Cast<UndoHistoryEntry>().Single(x=>Object.ReferenceEquals(x.Record,mixed));check(mixedRow.Unsupported==1&&mixedRow.Status==L.Text("undoHistory.partial")&&mixedRow.Count=="1 / 2","Mixed copy/overwrite transactions show partial reversibility rather than claiming the entire operation can be undone");undoTransactionsWindow.Transactions.SelectedItem=mixedRow;check(Convert.ToString(undoTransactionsWindow.UndoButton.Content)==L.Text("undoHistory.undoAvailable"),"Partially reversible transactions explicitly offer only available steps");
   string renamed=Path.Combine(active.CurrentPath,"journal-rename.txt");File.WriteAllText(renamed,"journal");var proof=UndoReceipt.Capture(renamed,renamed,true);string target=renamed+".new";File.Move(renamed,target);proof=UndoReceipt.Committed(proof,target);RecordUndoTransaction("Journal rename",new[]{proof});check(UndoTransactions().Any(x=>x.Title=="Journal rename"&&x.Group!=null&&x.Record!=null),"Direct rename receipts link to the persistent transaction journal");
   NextStageTests.Draw(undoTransactionsWindow,Path.Combine(Path.GetDirectoryName(active.CurrentPath),"undo-history.png"));undoTransactionsWindow.Close();
  }
 }
}
#endif
